"""Private Chromium over inherited CDP pipes; no debugger socket or external dependencies."""
import fcntl,json,os,pathlib,select,shutil,signal,tempfile,time
class Browser:
 def __init__(self):self.pid=None;self.writer=None;self.reader=None;self.pending=b'';self.sequence=0;self.events=[]
 def __enter__(self):
  assert os.name=='posix' and os.geteuid()!=0
  executable=shutil.which('chromium-headless-shell')
  if not executable:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: pinned Chromium headless addon missing')
  self.temp=tempfile.TemporaryDirectory(prefix='of-browser-');self.root=pathlib.Path(self.temp.name)
  self.log=(self.root/'browser.log').open('wb')
  pipes=[*os.pipe(),*os.pipe()]
  high=[fcntl.fcntl(fd,fcntl.F_DUPFD_CLOEXEC,10) for fd in pipes]
  for fd in pipes:os.close(fd)
  incoming,write,read,outgoing=high
  # fd3/fd4 may already hold the log or the assessment runner's own descriptors.
  # Keep a separate high descriptor before assigning Chromium's protocol pipes.
  log_copy=fcntl.fcntl(self.log.fileno(),fcntl.F_DUPFD_CLOEXEC,20)
  actions=[(os.POSIX_SPAWN_DUP2,log_copy,1),(os.POSIX_SPAWN_DUP2,log_copy,2),
    (os.POSIX_SPAWN_DUP2,incoming,3),(os.POSIX_SPAWN_DUP2,outgoing,4)]
  actions += [(os.POSIX_SPAWN_CLOSE,fd) for fd in [*high,log_copy]]
  args=[executable,'--no-sandbox','--headless','--disable-gpu','--disable-software-rasterizer',
   '--disable-dev-shm-usage','--remote-debugging-pipe','--no-first-run','--no-default-browser-check',
   '--disable-background-networking','--disable-component-update','--disable-sync','--disable-extensions',
   '--disable-breakpad','--no-proxy-server','--user-data-dir='+str(self.root/'profile'),'about:blank']
  try:
   self.pid=os.posix_spawn(executable,args,{**os.environ,'HOME':str(self.root),'XDG_CACHE_HOME':str(self.root/'cache')},file_actions=actions,setpgroup=0)
  except BaseException:
   for fd in [*high,log_copy]:os.close(fd)
   self.log.close();self.temp.cleanup();raise
  os.close(incoming);os.close(outgoing);os.close(log_copy);self.writer=write;self.reader=read
  try:
   self.version=self.call('Browser.getVersion')
   assert 'HeadlessChrome/156.0.8078.47' in self.version['product'] or 'Chrome/156.0.8078.47' in self.version['product'],self.version
   target=self.call('Target.createTarget',{'url':'about:blank'})['targetId']
   self.session=self.call('Target.attachToTarget',{'targetId':target,'flatten':True})['sessionId']
   self.call('Page.enable',session=self.session)
   print('NATIVE_CHROMIUM_156_CDP_PRIVATE_PIPE_READY',flush=True);return self
  except BaseException:self.__exit__(None,None,None);raise
 def call(self,method,params=None,session=None,timeout=8):
  self.sequence+=1;ident=self.sequence
  request={'id':ident,'method':method,'params':params or {}}
  if session:request['sessionId']=session
  wire=json.dumps(request,separators=(',',':')).encode()+b'\0';written=0
  while written<len(wire):written+=os.write(self.writer,wire[written:])
  deadline=time.monotonic()+timeout
  while True:
   if b'\0' in self.pending:
    raw,self.pending=self.pending.split(b'\0',1)
    if not raw:continue
    message=json.loads(raw)
    if message.get('id')==ident:
     if 'error' in message:raise AssertionError('CDP rejected '+method+': '+str(message['error']))
     return message.get('result',{})
    self.events.append(message);self.events=self.events[-200:]
   else:
    remaining=deadline-time.monotonic()
    if remaining<=0:raise AssertionError('CDP deadline '+method+': '+self.logs())
    ready,_,_=select.select([self.reader],[],[],remaining)
    if not ready:raise AssertionError('CDP deadline '+method+': '+self.logs())
    chunk=os.read(self.reader,65536)
    if not chunk:raise AssertionError('browser pipe closed '+method+': '+self.logs())
    self.pending+=chunk
 def evaluate(self,expression,timeout=8):
  result=self.call('Runtime.evaluate',{'expression':expression,'awaitPromise':True,'returnByValue':True,'timeout':5000},session=self.session,timeout=timeout)
  if result.get('exceptionDetails'):raise AssertionError('browser JavaScript rejected: '+str(result['exceptionDetails']))
  return result.get('result',{}).get('value')
 def navigate(self,url):
  result=self.call('Page.navigate',{'url':url},session=self.session)
  assert not result.get('errorText'),result
  deadline=time.monotonic()+5
  while time.monotonic()<deadline:
   try:
    if self.evaluate('document.readyState')=='complete':return
   except AssertionError:pass
   time.sleep(.03)
  raise AssertionError('browser document readiness deadline')
 def logs(self):return (self.root/'browser.log').read_text(errors='replace')[-2500:]
 def __exit__(self,*args):
  if self.pid is not None:
   try:os.killpg(self.pid,signal.SIGTERM)
   except ProcessLookupError:pass
   deadline=time.monotonic()+2;exited=False
   while time.monotonic()<deadline:
    if os.waitpid(self.pid,os.WNOHANG)[0]:exited=True;break
    time.sleep(.02)
   if not exited:
    try:os.killpg(self.pid,signal.SIGKILL)
    except ProcessLookupError:pass
    os.waitpid(self.pid,0)
   self.pid=None
  for fd in (self.writer,self.reader):
   if fd is not None:
    try:os.close(fd)
    except OSError:pass
  if hasattr(self,'log'):self.log.close()
  if hasattr(self,'temp'):self.temp.cleanup()

